<?php

declare(strict_types=1);

namespace core\presentation\controller;

use Yii;
use yii\web\Controller;
use yii\web\Response;
use yii\httpclient\Client;
use yii\helpers\Html;

class WelcomeController extends Controller
{
    public function actionIndex(): string
    {
        Yii::$app->response->format = Response::FORMAT_HTML;

        $catUrl = $this->fetchCatUrl();

        $catBlock = $catUrl !== null
            ? Html::img($catUrl, [
                'alt'   => 'Тут должен быть кот',
                'style' => 'max-width:100%;height:auto;border-radius:12px;margin-top:24px;box-shadow:0 8px 24px rgba(0,0,0,.15);',
            ])
            : '<p style="color:#888;font-style:italic;">К сожалению, котик не смог прийти. Попробуй обновить страницу.</p>';

        return <<<HTML
<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Script Agency TASKFLOW CRM | Welcome</title>
    <style>
        * { box-sizing: border-box; }
        body {
            margin: 0;
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%);
            color: #fff;
            padding: 24px;
        }
        .card {
            max-width: 720px;
            width: 100%;
            background: rgba(255, 255, 255, 0.04);
            border: 1px solid rgba(255, 255, 255, 0.15);
            border-radius: 16px;
            padding: 40px;
            backdrop-filter: blur(10px);
            text-align: center;
        }
        h1 {
            font-size: 28px;
            margin: 0 0 16px;
            font-weight: 700;
        }
        .badge {
            display: inline-block;
            padding: 4px 12px;
            border-radius: 999px;
            background: rgba(255, 255, 255, 0.15);
            font-size: 12px;
            letter-spacing: 1px;
            text-transform: uppercase;
            margin-bottom: 20px;
        }
        p {
            font-size: 16px;
            line-height: 1.6;
            margin: 12px 0;
            color: rgba(255, 255, 255, 0.9);
        }
        .muted { color: rgba(255, 255, 255, 0.65); font-size: 14px; }
    </style>
</head>
<body>
    <div class="card">
        <img style="width: 150px; display: inline-block" class="logo" src="data:image/svg+xml;base64," />
        <div>Script Agency TASKFLOW CRM</div>
        <h1>Добро пожаловать в сервис TASKFLOW CRM компании Script Agency</h1>
        <p>
            Этот сервис представляет собой <strong>API</strong> и служит
            для взаимодействия между приложениями.
        </p>
        <p>
            Мы рады, что ты пользуешься нашими сервисами и доверяешь нам свои данные.
            Вот тебе за это случайный кот 🐱
        </p>
        {$catBlock}
        <p class="muted" style="margin-top:32px;">
            &copy; Script Agency TASKFLOW CRM
        </p>
    </div>
</body>
</html>
HTML;
    }

    /**
     * Запрашивает случайного кота у cataas.com и возвращает абсолютный URL.
     */
    private function fetchCatUrl(): ?string
    {
        try {
            $client   = new Client();
            $response = $client->createRequest()
                ->setMethod('GET')
                ->setUrl('https://cataas.com/cat?json=true')
                ->setOptions(['timeout' => 5])
                ->send();

            if ($response->isOk && !empty($response->data['url'])) {
                return $response->data['url'];
            }

            Yii::warning('cataas вернул неожиданный ответ: ' . $response->content, 'welcome');
        } catch (\Throwable $e) {
            Yii::error('Не удалось получить кота: ' . $e->getMessage(), 'welcome');
        }

        return null;
    }
}
